SET XACT_ABORT ON;

BEGIN TRY
    BEGIN TRANSACTION;

    -- Primero eliminar tablas dependientes
    IF OBJECT_ID(N'silver.IncidenteRuta', N'U') IS NOT NULL
        DELETE FROM silver.IncidenteRuta;

    IF OBJECT_ID(N'silver.DemandaParadas', N'U') IS NOT NULL
        DELETE FROM silver.DemandaParadas;

    IF OBJECT_ID(N'silver.Viajes', N'U') IS NOT NULL
        DELETE FROM silver.Viajes;

    IF OBJECT_ID(N'silver.Incidentes', N'U') IS NOT NULL
        DELETE FROM silver.Incidentes;

    -- Después eliminar las tablas principales
    IF OBJECT_ID(N'silver.Rutas', N'U') IS NOT NULL
        DELETE FROM silver.Rutas;

    IF OBJECT_ID(N'silver.Paradas', N'U') IS NOT NULL
        DELETE FROM silver.Paradas;

    IF OBJECT_ID(N'silver.Vehiculos', N'U') IS NOT NULL
        DELETE FROM silver.Vehiculos;

    COMMIT TRANSACTION;

END TRY
BEGIN CATCH

    IF @@TRANCOUNT > 0
        ROLLBACK TRANSACTION;

    THROW;

END CATCH;
